function crushBoulders(stones) {
  const h = stones.slice(); let n = h.length;
  const down = i => { for (;;) { const l = 2 * i + 1, r = l + 1; let m = i; if (l < n && h[l] > h[m]) m = l; if (r < n && h[r] > h[m]) m = r; if (m === i) return; const t = h[i]; h[i] = h[m]; h[m] = t; i = m; } };
  const up = i => { while (i > 0) { const p = (i - 1) >> 1; if (h[p] >= h[i]) return; const t = h[p]; h[p] = h[i]; h[i] = t; i = p; } };
  for (let i = (n >> 1) - 1; i >= 0; i--) down(i);
  const pop = () => { const t = h[0]; n--; h[0] = h[n]; h.length = n; if (n) down(0); return t; };
  while (n > 1) { const y = pop(), x = pop(); if (y !== x) { h.push(y - x); n++; up(n - 1); } }
  return n ? h[0] : 0;
}
